use std::time::Instant;

fn main() {
    let runs = 10_000;
    let mut total_ns = 0u128;

    for _ in 0..runs {
        let mut memo: Vec<Option<u64>> = vec![None; 51];
        let start = Instant::now();
        let _ = fib(50, &mut memo);
